if (!acctMap[6300]) missing.push({ number: 6300, name: "Leie lokale" });
if (!acctMap[2920]) missing.push({ number: 2920, name: "Skyldig skatt" });
if (!acctMap[1700]) missing.push({ number: 1700, name: "Forskuddsbetalt leiekostnad" });

